import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p4_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor matrix_vector_mul(torch::Tensor A, torch::Tensor B);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matrix_vector_mul", &matrix_vector_mul, "Matrix-vector multiply (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 256

__global__ void gemv_float4_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int K)
{
    int row = blockIdx.x;
    if (row >= M) return;

    const float* a_row = A + row * K;
    float sum = 0.0f;

    // float4 vectorized loads
    int K4 = K / 4;
    const float4* a4 = reinterpret_cast<const float4*>(a_row);
    const float4* b4 = reinterpret_cast<const float4*>(B);

    for (int i = threadIdx.x; i < K4; i += BLOCK_SIZE) {
        float4 av = a4[i];
        float4 bv = b4[i];
        sum += av.x * bv.x + av.y * bv.y + av.z * bv.z + av.w * bv.w;
    }

    // scalar tail
    int tail_start = K4 * 4;
    for (int i = tail_start + threadIdx.x; i < K; i += BLOCK_SIZE) {
        sum += a_row[i] * B[i];
    }

    // warp reduction
    unsigned mask = 0xffffffff;
    for (int offset = 16; offset > 0; offset >>= 1)
        sum += __shfl_down_sync(mask, sum, offset);

    // block reduction via shared memory
    __shared__ float smem[BLOCK_SIZE / 32];
    int lane = threadIdx.x & 31;
    int warp = threadIdx.x >> 5;
    if (lane == 0) smem[warp] = sum;
    __syncthreads();

    if (warp == 0) {
        sum = (lane < (BLOCK_SIZE / 32)) ? smem[lane] : 0.0f;
        for (int offset = (BLOCK_SIZE / 32) >> 1; offset > 0; offset >>= 1)
            sum += __shfl_down_sync(mask, sum, offset);
        if (lane == 0) C[row] = sum;
    }
}

torch::Tensor matrix_vector_mul(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "Inputs must be CUDA tensors");
    TORCH_CHECK(A.dtype() == torch::kFloat32 && B.dtype() == torch::kFloat32, "Inputs must be float32");
    TORCH_CHECK(A.dim() == 2, "A must be 2D");
    TORCH_CHECK(B.dim() == 2 && B.size(1) == 1, "B must be shape (K, 1)");

    A = A.contiguous();
    B = B.contiguous();

    int M = A.size(0);
    int K = A.size(1);

    auto C = torch::empty({M, 1}, A.options());

    dim3 grid(M);
    dim3 block(BLOCK_SIZE);

    gemv_float4_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K
    );

    return C;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs matrix-vector multiplication (C = A * B).
        """
    def __init__(self):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        # <<<END_IMPROVE>>>

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        if (A.is_cuda and B.is_cuda and
                    A.dtype == torch.float32 and B.dtype == torch.float32 and
                    A.dim() == 2 and B.dim() == 2 and B.size(1) == 1):
                    return _stark_get_extension().matrix_vector_mul(A, B)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        return torch.matmul(A, B)
        # <<<END_IMPROVE>>>

