CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cublas_v2.h>
#include <ATen/cuda/CUDAContext.h>

torch::Tensor matrix_vector_mul(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "Inputs must be CUDA tensors");
    TORCH_CHECK(A.dtype() == torch::kFloat32 && B.dtype() == torch::kFloat32, "Inputs must be float32");
    TORCH_CHECK(A.dim() == 2, "A must be 2D");
    TORCH_CHECK(B.dim() == 2 && B.size(1) == 1, "B must be shape (K, 1)");

    A = A.contiguous();
    B = B.contiguous();

    int M = (int)A.size(0);
    int K = (int)A.size(1);

    auto C = torch::zeros({M, 1}, A.options());

    cublasHandle_t handle = at::cuda::getCurrentCUDABlasHandle();

    // PyTorch stores A in row-major (C order): A[M,K].
    // cuBLAS is column-major. Treat A as column-major A_cm[K,M].
    // We want C = A * B, i.e. C[M,1] = A[M,K] * B[K,1].
    // In column-major terms: C_cm[M,1] = A_cm^T[M,K] * B_cm[K,1]
    // => cublasSgemv with CUBLAS_OP_T, m=K, n=M, lda=K
    //    computes y = alpha * A_cm^T * x + beta * y
    //    where A_cm is K x M (lda=K), x is length M, y is length K -- wrong.
    //
    // Correct mapping:
    // cublasSgemv(handle, CUBLAS_OP_N, m, n, alpha, A, lda, x, incx, beta, y, incy)
    // computes y = alpha * op(A) * x + beta * y
    // With CUBLAS_OP_N: y[m] = alpha * A[m x n] * x[n] + beta * y[m]
    // We want: C[M] = A_row_major[M,K] * B[K]
    // Treat A_row_major as column-major A_cm[K,M] (lda=K).
    // Use CUBLAS_OP_T: op(A_cm) = A_cm^T which is [M,K] in col-major = A_row_major.
    // So: y[M] = alpha * A_cm^T[M,K] * x[K] + beta * y[M]
    // => cublasSgemv(handle, CUBLAS_OP_T, K, M, &alpha, A_ptr, K, B_ptr, 1, &beta, C_ptr, 1)

    const float alpha = 1.0f;
    const float beta  = 0.0f;

    cublasStatus_t status = cublasSgemv(
        handle,
        CUBLAS_OP_T,
        K,   // m (rows of A_cm = K)
        M,   // n (cols of A_cm = M)
        &alpha,
        A.data_ptr<float>(),  // A_cm pointer
        K,                    // lda
        B.data_ptr<float>(),  // x vector of length K
        1,
        &beta,
        C.data_ptr<float>(),  // y vector of length M
        1
    );

    TORCH_CHECK(status == CUBLAS_STATUS_SUCCESS, "cublasSgemv failed with status ", (int)status);

    return C;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs matrix-vector multiplication (C = A * B).
        """
    def __init__(self):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        # <<<END_IMPROVE>>>

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        if (A.is_cuda and B.is_cuda and
                        A.dtype == torch.float32 and B.dtype == torch.float32 and
                        A.dim() == 2 and B.dim() == 2 and B.size(1) == 1):
                    return _stark_get_extension().matrix_vector_mul(A, B)
        # <<<END_IMPROVE>>>
