CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define ROWS_PER_BLOCK 4
#define THREADS 256
#define TILE_K 256

__global__ void gemv_multi_row_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M, int K)
{
    // Each block handles ROWS_PER_BLOCK consecutive rows
    int block_row = blockIdx.x * ROWS_PER_BLOCK;
    int tid = threadIdx.x;

    // Shared memory for B tile and reduction
    __shared__ float s_B[TILE_K];
    __shared__ float s_reduce[ROWS_PER_BLOCK][THREADS];

    // Per-thread accumulators for each row
    float acc[ROWS_PER_BLOCK] = {0.f, 0.f, 0.f, 0.f};

    // Determine valid rows
    int valid_rows = min(ROWS_PER_BLOCK, M - block_row);

    // Loop over K in tiles
    for (int k_base = 0; k_base < K; k_base += TILE_K) {
        int tile_end = min(TILE_K, K - k_base);

        // Cooperatively load B tile into shared memory
        for (int i = tid; i < tile_end; i += THREADS) {
            s_B[i] = B[k_base + i];
        }
        __syncthreads();

        // Each thread accumulates over the tile for each row
        // Use float4 when possible
        int vec_end = (tile_end / 4) * 4;
        for (int i = tid * 4; i < vec_end; i += THREADS * 4) {
            float4 bv = *reinterpret_cast<const float4*>(&s_B[i]);
            for (int r = 0; r < valid_rows; r++) {
                const float* A_row = A + (block_row + r) * K + k_base;
                float4 av = *reinterpret_cast<const float4*>(&A_row[i]);
                acc[r] += av.x * bv.x + av.y * bv.y + av.z * bv.z + av.w * bv.w;
            }
        }
        // Handle tail
        for (int i = vec_end + tid; i < tile_end; i += THREADS) {
            float bv = s_B[i];
            for (int r = 0; r < valid_rows; r++) {
                acc[r] += A[(block_row + r) * K + k_base + i] * bv;
            }
        }
        __syncthreads();
    }

    // Block-level reduction for each row
    for (int r = 0; r < valid_rows; r++) {
        s_reduce[r][tid] = acc[r];
    }
    __syncthreads();

    for (int r = 0; r < valid_rows; r++) {
        // Tree reduction
        for (int stride = THREADS / 2; stride > 0; stride >>= 1) {
            if (tid < stride) {
                s_reduce[r][tid] += s_reduce[r][tid + stride];
            }
            __syncthreads();
        }
        if (tid == 0) {
            C[block_row + r] = s_reduce[r][0];
        }
    }
}

torch::Tensor matrix_vector_mul(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "Inputs must be CUDA tensors");
    TORCH_CHECK(A.dtype() == torch::kFloat32 && B.dtype() == torch::kFloat32, "Inputs must be float32");
    TORCH_CHECK(A.dim() == 2, "A must be 2D");
    TORCH_CHECK(B.dim() == 2 && B.size(1) == 1, "B must be shape (K, 1)");

    A = A.contiguous();
    B = B.contiguous();

    int M = (int)A.size(0);
    int K = (int)A.size(1);

    auto C = torch::empty({M, 1}, A.options());

    int grid_x = (M + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK;
    dim3 grid(grid_x);
    dim3 block(THREADS);

    gemv_multi_row_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K
    );

    return C;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs matrix-vector multiplication (C = A * B).
        """
    def __init__(self):
        super().__init__()
