# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define WARPS_PER_BLOCK 4
#define WARP_SIZE 32

__global__ void warp_gemv_kernel(const float* __restrict__ A,
                                  const float* __restrict__ B,
                                  float* __restrict__ C,
                                  int M, int K) {
    int warp_id_in_block = threadIdx.x / WARP_SIZE;
    int lane = threadIdx.x % WARP_SIZE;
    int row = blockIdx.x * WARPS_PER_BLOCK + warp_id_in_block;
    if (row >= M) return;

    const float* a_row = A + (long long)row * K;
    float sum = 0.0f;

    // Each lane strides over K with step=32
    // Use float4 vectorized loads where possible
    int k4_end = (K / 4) * 4;  // largest multiple of 4
    // Each lane handles indices: lane, lane+32, lane+64, ...
    // For float4: each lane loads 4 consecutive floats at position base+lane*4
    // Actually let's do scalar with unrolling for simplicity and correctness
    int k = lane;
    #pragma unroll 8
    for (; k + 7*WARP_SIZE < K; k += 8*WARP_SIZE) {
        sum += a_row[k]                * __ldg(&B[k]);
        sum += a_row[k + WARP_SIZE]   * __ldg(&B[k + WARP_SIZE]);
        sum += a_row[k + 2*WARP_SIZE] * __ldg(&B[k + 2*WARP_SIZE]);
        sum += a_row[k + 3*WARP_SIZE] * __ldg(&B[k + 3*WARP_SIZE]);
        sum += a_row[k + 4*WARP_SIZE] * __ldg(&B[k + 4*WARP_SIZE]);
        sum += a_row[k + 5*WARP_SIZE] * __ldg(&B[k + 5*WARP_SIZE]);
        sum += a_row[k + 6*WARP_SIZE] * __ldg(&B[k + 6*WARP_SIZE]);
        sum += a_row[k + 7*WARP_SIZE] * __ldg(&B[k + 7*WARP_SIZE]);
    }
    for (; k < K; k += WARP_SIZE) {
        sum += a_row[k] * __ldg(&B[k]);
    }

    // Warp-level reduction using shuffle
    sum += __shfl_down_sync(0xffffffff, sum, 16);
    sum += __shfl_down_sync(0xffffffff, sum, 8);
    sum += __shfl_down_sync(0xffffffff, sum, 4);
    sum += __shfl_down_sync(0xffffffff, sum, 2);
    sum += __shfl_down_sync(0xffffffff, sum, 1);

    if (lane == 0) {
        C[row] = sum;
    }
}

torch::Tensor matrix_vector_mul_warp(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "Inputs must be CUDA tensors");
    TORCH_CHECK(A.dtype() == torch::kFloat32 && B.dtype() == torch::kFloat32, "Inputs must be float32");
    TORCH_CHECK(A.dim() == 2, "A must be 2D");
    TORCH_CHECK(B.dim() == 2 && B.size(1) == 1, "B must be shape (K, 1)");
    TORCH_CHECK(A.size(1) == B.size(0), "Dimension mismatch");

    A = A.contiguous();
    B = B.contiguous();

    int M = (int)A.size(0);
    int K = (int)A.size(1);

    auto C = torch::zeros({M, 1}, A.options());

    int blocks = (M + WARPS_PER_BLOCK - 1) / WARPS_PER_BLOCK;
    int threads = WARPS_PER_BLOCK * WARP_SIZE;

    warp_gemv_kernel<<<blocks, threads>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M, K
    );

    return C;
}
